- **ruamel.yaml**: a diferencia de PyYAML, conserva los comentarios y los números de línea. Así el script puede extraer la descripción de cada valor, incluida la convención `# --` de helm-docs.
- **rich**: muestra la salida en una tabla legible en terminal.

```python
#!/usr/bin/env python3
"""
Parsea un Helm chart (directorio o paquete .tgz) y lista sus valores por defecto.

Para cada valor muestra la ruta en formato --set, el tipo, el valor por defecto
y la descripción tomada de los comentarios de values.yaml. También recorre
los subcharts de charts/, tanto en directorio como empaquetados en .tgz.

Uso:
    python helm_values.py ./mi-chart
    python helm_values.py mi-chart-1.2.3.tgz --format json
    python helm_values.py ./mi-chart --filter ingress --no-subcharts
"""
from __future__ import annotations

import argparse
import io
import json
import re
import sys
import tarfile
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Iterator

from rich.console import Console
from rich.table import Table
from rich.text import Text
from ruamel.yaml import YAML
from ruamel.yaml.comments import CommentedMap

yaml = YAML(typ="rt")  # round-trip: conserva comentarios y posiciones

SUBCHART_TGZ = re.compile(r"charts/[^/]+\.tgz")


@dataclass
class ValueRow:
    key: str
    type: str
    default: str
    description: str


@dataclass
class Chart:
    name: str
    version: str
    app_version: str
    description: str
    rows: list[ValueRow]
    subcharts: list["Chart"] = field(default_factory=list)


# --------------------------------------------------------------------------
# Lectura de ficheros (directorio o .tgz) a un dict {ruta_relativa: bytes}
# --------------------------------------------------------------------------

def _is_relevant(rel: str) -> bool:
    name = rel.rsplit("/", 1)[-1]
    return name in ("Chart.yaml", "values.yaml") or bool(SUBCHART_TGZ.fullmatch(rel))


def files_from_dir(root: Path) -> dict[str, bytes]:
    files = {}
    for p in root.rglob("*"):
        rel = p.relative_to(root).as_posix()
        if p.is_file() and _is_relevant(rel):
            files[rel] = p.read_bytes()
    return files


def files_from_tar(tf: tarfile.TarFile) -> dict[str, bytes]:
    # Se lee todo en memoria, sin extraer nada a disco. Los paquetes de Helm
    # tienen siempre un directorio raíz (mi-chart/...), que se elimina.
    files = {}
    for member in tf.getmembers():
        if not member.isfile() or "/" not in member.name:
            continue
        rel = member.name.split("/", 1)[1]
        if _is_relevant(rel):
            fh = tf.extractfile(member)
            if fh is not None:
                files[rel] = fh.read()
    return files


# --------------------------------------------------------------------------
# Construcción del modelo del chart
# --------------------------------------------------------------------------

def build_chart(files: dict[str, bytes], include_subcharts: bool = True) -> Chart:
    if "Chart.yaml" not in files:
        raise ValueError("No se encontró Chart.yaml: ¿es un Helm chart válido?")

    meta = yaml.load(files["Chart.yaml"]) or {}
    raw_values = files.get("values.yaml", b"").decode("utf-8-sig")
    values = yaml.load(raw_values) if raw_values.strip() else CommentedMap()
    lines = raw_values.splitlines()

    chart = Chart(
        name=str(meta.get("name", "?")),
        version=str(meta.get("version", "?")),
        app_version=str(meta.get("appVersion", "")),
        description=str(meta.get("description", "")),
        rows=list(flatten(values, lines)) if isinstance(values, dict) else [],
    )

    if include_subcharts:
        # Subcharts como directorio: charts/<nombre>/...
        sub_dirs = sorted({p.split("/")[1] for p in files
                           if p.startswith("charts/") and p.count("/") >= 2})
        for d in sub_dirs:
            prefix = f"charts/{d}/"
            sub_files = {k[len(prefix):]: v for k, v in files.items() if k.startswith(prefix)}
            if "Chart.yaml" in sub_files:
                chart.subcharts.append(build_chart(sub_files))
        # Subcharts empaquetados: charts/<nombre>.tgz
        for p in sorted(files):
            if SUBCHART_TGZ.fullmatch(p):
                with tarfile.open(fileobj=io.BytesIO(files[p]), mode="r:*") as tf:
                    chart.subcharts.append(build_chart(files_from_tar(tf)))
    return chart


def load_chart(path: Path, include_subcharts: bool = True) -> Chart:
    if path.is_dir():
        files = files_from_dir(path)
    elif path.is_file() and tarfile.is_tarfile(path):
        with tarfile.open(path, mode="r:*") as tf:
            files = files_from_tar(tf)
    else:
        raise ValueError(f"'{path}' no es un directorio ni un paquete .tgz")
    return build_chart(files, include_subcharts)


# --------------------------------------------------------------------------
# Aplanado de values.yaml y extracción de comentarios
# --------------------------------------------------------------------------

def yaml_type(v: Any) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "map"
    return type(v).__name__


def render(v: Any) -> str:
    return json.dumps(v, ensure_ascii=False, default=str)


def _clean_comment(line: str) -> str:
    text = line.strip().lstrip("#").strip()
    return text[2:].strip() if text.startswith("--") else text  # convención helm-docs


def comment_above(lines: list[str], line_no: int | None) -> str:
    """Bloque de comentarios contiguo justo encima de la línea indicada."""
    if line_no is None:
        return ""
    collected = []
    i = line_no - 1
    while i >= 0 and lines[i].strip().startswith("#"):
        collected.append(_clean_comment(lines[i]))
        i -= 1
    return " ".join(reversed([c for c in collected if c]))


def inline_comment(node: CommentedMap, key: Any) -> str:
    """Comentario al final de la línea (clave: valor  # comentario)."""
    item = node.ca.items.get(key)
    if not item or len(item) < 3 or item[2] is None:
        return ""
    # ruamel agrupa aquí los comentarios de las líneas siguientes: solo la primera
    first = item[2].value.splitlines()[0] if item[2].value else ""
    return _clean_comment(first)


def flatten(node: dict, lines: list[str], prefix: str = "") -> Iterator[ValueRow]:
    for k, v in node.items():
        # Helm exige escapar los puntos de las claves en --set
        key = str(k).replace(".", r"\.")
        path = f"{prefix}.{key}" if prefix else key

        line_no = None
        desc_inline = ""
        if isinstance(node, CommentedMap):
            line_no = node.lc.key(k)[0]
            desc_inline = inline_comment(node, k)
        desc = " ".join(filter(None, [comment_above(lines, line_no), desc_inline]))

        if isinstance(v, dict) and v:
            yield from flatten(v, lines, path)
        else:
            yield ValueRow(path, yaml_type(v), render(v), desc)


# --------------------------------------------------------------------------
# Salida
# --------------------------------------------------------------------------

def iter_charts(chart: Chart, prefix: str = "") -> Iterator[tuple[str, Chart]]:
    """Recorre chart y subcharts, devolviendo el prefijo con el que el padre
    sobrescribe sus valores (p. ej. 'redis.')."""
    yield prefix, chart
    for sub in chart.subcharts:
        yield from iter_charts(sub, f"{prefix}{sub.name}.")


def print_table(chart: Chart, needle: str | None, console: Console) -> None:
    for prefix, c in iter_charts(chart):
        rows = [r for r in c.rows
                if not needle or needle in r.key.lower() or needle in r.description.lower()]
        if not rows:
            continue
        title = f"{c.name} {c.version}"
        if c.app_version:
            title += f" (app {c.app_version})"
        if prefix:
            title += f"  —  subchart, sobrescribir con '{prefix}<clave>'"
        table = Table(title=title, title_justify="left", show_lines=False, expand=True)
        table.add_column("Clave", style="cyan", overflow="fold")
        table.add_column("Tipo", style="magenta", no_wrap=True)
        table.add_column("Por defecto", style="green", overflow="fold", max_width=50)
        table.add_column("Descripción", overflow="fold")
        for r in rows:
            # Text() evita que rich interprete corchetes del valor como markup
            table.add_row(Text(prefix + r.key), Text(r.type), Text(r.default), Text(r.description))
        console.print(table)
        console.print()


def to_json(chart: Chart, needle: str | None) -> str:
    out = []
    for prefix, c in iter_charts(chart):
        out.append({
            "chart": c.name,
            "version": c.version,
            "appVersion": c.app_version,
            "overridePrefix": prefix,
            "values": [asdict(r) for r in c.rows
                       if not needle or needle in r.key.lower() or needle in r.description.lower()],
        })
    return json.dumps(out, indent=2, ensure_ascii=False)


def main() -> int:
    parser = argparse.ArgumentParser(description="Lista los valores de un Helm chart.")
    parser.add_argument("chart", type=Path, help="Directorio del chart o paquete .tgz")
    parser.add_argument("--format", choices=["table", "json"], default="table")
    parser.add_argument("--filter", help="Mostrar solo claves/descripciones que contengan este texto")
    parser.add_argument("--no-subcharts", action="store_true", help="Ignorar charts/")
    args = parser.parse_args()

    try:
        chart = load_chart(args.chart, include_subcharts=not args.no_subcharts)
    except (ValueError, OSError, tarfile.TarError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1

    needle = args.filter.lower() if args.filter else None
    if args.format == "json":
        print(to_json(chart, needle))
    else:
        console = Console()
        if chart.description:
            console.print(f"[bold]{chart.name}[/bold]: {Text(chart.description)}\n")
        print_table(chart, needle, console)
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

**Comportamiento del script:**

- **Entrada**: acepta un directorio del chart o un `.tgz` generado con `helm package` o descargado con `helm pull`. Los `.tgz` se leen en memoria, sin extraer nada a disco, así que un paquete malicioso no puede escribir fuera de su sitio.
- **Claves**: se muestran en la notación de `--set`. Por ejemplo, `ingress.annotations.kubernetes\.io/ingress\.class` lleva escapados los puntos que forman parte del nombre de la clave.
- **Descripciones**: se toman del bloque de comentarios justo encima de cada clave y del comentario al final de la línea. Se elimina el prefijo `# --` de helm-docs.
- **Mapas y listas**: los mapas vacíos (`{}`) y las listas se muestran como hojas en JSON compacto, por ejemplo `tolerations: []`.
- **Subcharts**: aparecen con el prefijo con el que el chart padre los sobrescribe (`redis.auth.enabled`). Si en `dependencies` se usa un `alias`, el prefijo real es el alias y no el nombre del chart; el script no resuelve ese caso.

**Limitación**: el script lee los valores por defecto estáticos de `values.yaml`. No renderiza plantillas ni aplica ficheros `-f` adicionales. Para obtener los valores efectivos ya combinados, usa `helm show values` o `helm template`.
